import {lerp} from '@ge/sdk';
export function onEvent(c,e) {
  const s=c.state,p=c.parameters;
  if(e.kind==='item.activated')return {timers:[{action:'set',key:'clock',afterTicks:1,payload:{}}]};
  if(e.kind==='timer.fired'&&e.payload.key==='clock')return {nextState:{...s,cooldown:Math.max(0,s.cooldown-1)},timers:[{action:'set',key:'clock',afterTicks:1,payload:{}}]};
  if(e.kind==='item.used') {
    if(s.cooldown>0||c.activities.length)return {feedback:[{cueId:'blocked'}]};
    return {activities:[{action:'begin',key:'pulse',phase:'charging',data:{}}],timers:[{action:'set',key:'release',activityKey:'pulse',afterTicks:p.chargeTicks,payload:{}}]};
  }
  if(e.kind==='actor.move.sampled'&&c.activities.length) {
    const a=e.payload.from,b=e.payload.to;
    if(Math.hypot(a.x-b.x,a.z-b.z)>.25)return {activities:[{action:'end',key:'pulse',reason:'moved'}],feedback:[{cueId:'blocked'}]};
  }
  if(e.kind==='timer.fired'&&e.payload.key==='release') {
    const q=c.query('entity.nearby',{radius:p.radius,limit:8});
    if(!q.ok||q.data.entities.length===0)return {activities:[{action:'end',key:'pulse',reason:'no target'}],feedback:[{cueId:'blocked'}]};
    const a=c.self.position;
    return {activities:[{action:'update',key:'pulse',phase:'releasing'}],operations:q.data.entities.map((t,i)=>{let x=t.position.x-a.x,z=t.position.z-a.z,d=Math.hypot(x,z)||1;return {key:'push'+i,capability:'entity.velocity.add',activityKey:'pulse',args:{target:t.ref,deltaVelocity:{x:x/d*p.strength,y:.15,z:z/d*p.strength}}}})};
  }
  if(e.kind==='operation.results') {
    const ok=e.payload.receipts.filter(r=>r.status==='APPLIED');
    return {nextState:{cooldown:p.cooldownTicks,uses:s.uses+(ok.length?1:0)},activities:[{action:'end',key:'pulse',reason:'complete'}],feedback:ok.length?[{cueId:'release',receiptIds:ok.map(r=>r.receiptId)}]:[{cueId:'blocked'}]};
  }
  return {};
}
export function render(c,f) {
  const a=f.anchors.actor,points=[],release=f.cueId==='release';
  for(let i=0;i<24;i++){const t=i/24*Math.PI*2+f.elapsedTicks*.15,r=release?Math.min(c.parameters.radius,.3+f.elapsedTicks*.25):lerp(2,.5,Math.min(1,f.elapsedTicks/c.parameters.chargeTicks));points.push({worldId:a.worldId,x:a.x+Math.cos(t)*r,y:a.y+.2+Math.sin(t*3+f.elapsedTicks*.3)*.15,z:a.z+Math.sin(t)*r})}
  return {primitives:[{kind:'particle',key:'ring',particleKey:'minecraft:end_rod',points,countPerPoint:1},{kind:'text',key:'stage',channel:'actionbar',text:release?'脉冲已施加':'站稳，正在蓄力',ttlTicks:2}]};
}
